package glitch

import data.glitch_lib

# Issue tracker URL patterns
issue_url_patterns := [
    `issues/\d+`,
    `bugs/\d+`,
    `tickets/\d+`,
    `defects/\d+`,
    `vulnerabilities/\d+`,
    `CVE-\d+`,
    `GHSA-`,
]

# Action-required markers
action_markers := [
    `TODO`,
    `FIXME`,
    `HACK`,
    `XXX`,
    `OPTIMIZE`,
    `REFACTOR`,
]

# Workaround phrases
workaround_phrases := [
    `because\s+https?://`,
    `\bworkaround\b`,
    `\bcannot\s+change\b`,
    `\bwill\s+break\b`,
]

# Security-specific concerns
security_markers := [
    `\bHARDCOD(?:ED?|ING)\b`,
    `\bPLACEHOLDER\b`,
    `\bDUMMY\b`,
    `\bREMOVE\s+BEFORE\b`,
    `\bDO\s+NOT\s+DEPLOY\b`,
    `\bNOT\s+FOR\s+PRODUCTION\b`,
    `\bINSECURE\b`,
    `\bDANGEROUS\b`,
    `\bRISKY\b`,
    `\b(?:SECURITY|AUTHN?|AUTHZ?|ENCRYPT|VALIDATE)\b.*\b(?:BYPASSED?|MISSING|WEAK|DISABLED?)\b`,
]

# Temporal/status markers
temporal_markers := [
    `\bDEPRECATED\b`,
    `\bTEMPORARY\b`,
    `\bWORKAROUND\b`,
    `\bBYPASS\b`,
    `\bDISABLED\b`,
    `\bFOR\s+NOW\b`,
    `\bNEEDS?\s+REVIEW\b`,
]

# IaC context-specific markers
iac_context_markers := [
    `\ballow\s+all\s+for\s+testing\b`,
    `\btemporary\s+broad\s+access\b`,
    `\bskip\s+tls\s+verify\b`,
    `\bHTTP\s+only\s+for\s+now\b`,
    `\bdefault\s+admin\s+password\b`,
    `\bweak\s+key\s+for\s+dev\b`,
    `\boverriding\s+CIS\s+benchmark\b`,
    `\bnon[\-]?compliant\s+but\s+required\b`,
]

has_tracker_url(content) {
    pattern := issue_url_patterns[_]
    regex.match(pattern, content)
}

has_workaround_phrase(content) {
    pattern := workaround_phrases[_]
    regex.match(sprintf("(?i)%s", [pattern]), content)
}

has_security_marker(content) {
    pattern := security_markers[_]
    regex.match(sprintf("(?i)%s", [pattern]), content)
}

has_action_marker(content) {
    pattern := action_markers[_]
    regex.match(sprintf("(?i)\\b%s\\b", [pattern]), content)
}

has_iac_context_marker(content) {
    pattern := iac_context_markers[_]
    regex.match(sprintf("(?i)%s", [pattern]), content)
}

has_temporal_marker(content) {
    pattern := temporal_markers[_]
    regex.match(sprintf("(?i)%s", [pattern]), content)
}

is_suspicious(content) {
    has_tracker_url(content)
} else {
    has_workaround_phrase(content)
} else {
    has_security_marker(content)
} else {
    has_action_marker(content)
} else {
    has_iac_context_marker(content)
} else {
    has_temporal_marker(content)
}

suspicion_desc(content) = desc {
    has_tracker_url(content)
    desc := "Suspicious comment referencing an issue tracker or known vulnerability. (CWE-546)"
} else = desc {
    has_workaround_phrase(content)
    desc := "Suspicious comment indicating a workaround or temporary fix for a known issue. (CWE-546)"
} else = desc {
    has_security_marker(content)
    desc := "Suspicious comment indicating security shortcuts, insecure practices, or deferred security controls. (CWE-546)"
} else = desc {
    has_action_marker(content)
    desc := "Suspicious comment indicating incomplete implementation or known issues requiring action. (CWE-546)"
} else = desc {
    has_iac_context_marker(content)
    desc := "Suspicious comment indicating security exceptions or non-compliant configuration. (CWE-546)"
} else = desc {
    has_temporal_marker(content)
    desc := "Suspicious comment indicating a deprecated, temporary, or conditional state. (CWE-546)"
}

# Detect explicit Comment nodes
Glitch_Analysis[result] {
    walk(input, [_, node])
    node.ir_type == "Comment"
    content := node.content
    content != ""
    is_suspicious(content)

    result := {
        "type": "sec_susp_comm",
        "element": node,
        "path": input.path,
        "description": suspicion_desc(content),
    }
}

# Detect comments embedded in code strings of non-Comment nodes
Glitch_Analysis[result] {
    walk(input, [_, node])
    node.ir_type != "Comment"
    node.code != ""

    regex.match(`(?m)^\s*(?:#[^!]|//)`, node.code)
    content := node.code
    is_suspicious(content)

    result := {
        "type": "sec_susp_comm",
        "element": node,
        "path": input.path,
        "description": suspicion_desc(content),
    }
}

